window.PZ_PY_SOURCES = {
 "alphapy/__init__.py": "\"\"\"alphaPy: marimo-style reactive notebooks for alphaCentaur (see python/README.md).\"\"\"\n",
 "alphapy/display.py": "\"\"\"How a cell's result is shown: a value becomes an Output, {mime, data}.\n\nThe page draws text/plain, text/markdown (alphaMarkdown's renderer, with the\nproject's macros), text/html (in a sandboxed frame), image/png, image/svg+xml,\ntext/latex (KaTeX), widgets and stacks. Objects choose how they look the usual\nways: marimo's _mime_(), or IPython's _repr_html_/_repr_markdown_/\n_repr_latex_/_repr_svg_/_repr_png_. matplotlib figures become PNGs.\n\"\"\"\nimport base64\nimport io\nimport re\n\nfrom . import ui\n\nLIMIT = 4_000_000  # characters of output data per cell\n\n\nclass Html:\n    \"\"\"mo.Html(text): show HTML (in a sandboxed frame on the page).\"\"\"\n\n    def __init__(self, text):\n        self.text = str(text)\n\n    def _mime_(self):\n        return 'text/html', self.text\n\n    def __repr__(self):\n        return f'Html({self.text[:60]!r})'\n\n\nclass Markdown(Html):\n    \"\"\"mo.md(text): Markdown with math, rendered as alphaMarkdown renders notes.\"\"\"\n\n    def _mime_(self):\n        return 'text/markdown', self.text\n\n    def __format__(self, spec):\n        return self.text\n\n    def __str__(self):\n        return self.text\n\n\ndef md(text):\n    return Markdown(_dedent(str(text)))\n\n\ndef _dedent(text):\n    \"\"\"Markdown written inside an indented triple-quoted string.\"\"\"\n    lines = text.split('\\n')\n    while lines and not lines[0].strip():\n        lines.pop(0)\n    while lines and not lines[-1].strip():\n        lines.pop()\n    indents = [len(l) - len(l.lstrip()) for l in lines if l.strip()]\n    cut = min(indents) if indents else 0\n    return '\\n'.join(l[cut:] for l in lines)\n\n\nclass Stack:\n    def __init__(self, items, direction, gap=0.5, align=None, justify=None):\n        self.items, self.direction, self.gap, self.align, self.justify = list(items), direction, gap, align, justify\n\n    def _output(self):\n        return {'mime': 'application/vnd.alphapy.stack+json', 'data': {\n            'direction': self.direction, 'gap': self.gap, 'align': self.align, 'justify': self.justify,\n            'items': [format_value(x) or {'mime': 'text/plain', 'data': ''} for x in self.items]}}\n\n\ndef hstack(items, gap=0.5, align=None, justify='start', **_):\n    return Stack(items, 'h', gap, align, justify)\n\n\ndef vstack(items, gap=0.5, align=None, justify='start', **_):\n    return Stack(items, 'v', gap, align, justify)\n\n\ndef as_html(value):\n    \"\"\"mo.as_html(value): a value shown the way a cell would show it.\"\"\"\n    out = format_value(value)\n    return _Shown(out)\n\n\nclass _Shown:\n    def __init__(self, output):\n        self.output = output\n\n    def _output(self):\n        return self.output\n\n\nclass MarimoStopError(Exception):\n    \"\"\"mo.stop(...): end the cell here, showing `output` (and skip the cells that use it).\"\"\"\n\n    def __init__(self, output=None):\n        super().__init__('mo.stop')\n        self.output = output\n\n\ndef stop(predicate, output=None):\n    if predicate:\n        raise MarimoStopError(output)\n\n\nCALLOUT_KINDS = ('neutral', 'info', 'success', 'warn', 'danger')\n\n\nclass Callout(Markdown):\n    \"\"\"A highlighted note: Markdown drawn in a box tinted for its kind.\"\"\"\n\n    def __init__(self, text, kind):\n        super().__init__(text)\n        self.kind = kind if kind in CALLOUT_KINDS else 'neutral'\n\n    def _output(self):\n        return {**_markdown_with_widgets(self.text), 'callout': self.kind}\n\n\ndef callout(value, kind='neutral'):\n    \"\"\"mo.callout(value, kind): kind is neutral, info, success, warn or danger.\"\"\"\n    out = format_value(value)\n    body = out['data'] if out and out['mime'] in ('text/markdown', 'text/plain') else str(value)\n    return Callout(str(body), kind)\n\n\n# ------------------------------------------------------------ formatting\ndef _figure_png(fig):\n    buf = io.BytesIO()\n    fig.savefig(buf, format='png', dpi=110, bbox_inches='tight')\n    return {'mime': 'image/png', 'data': base64.b64encode(buf.getvalue()).decode('ascii')}\n\n\ndef _matplotlib_figure(value):\n    \"\"\"The figure behind a Figure, Axes, Artist, or a list of artists (e.g. plt.plot's result).\"\"\"\n    import sys\n    if 'matplotlib' not in sys.modules:\n        return None\n    try:\n        from matplotlib.figure import Figure\n        from matplotlib.artist import Artist\n    except Exception:\n        return None\n    if isinstance(value, Figure):\n        return value\n    if isinstance(value, Artist):\n        return value.get_figure()\n    if isinstance(value, (list, tuple)) and value and all(isinstance(v, Artist) for v in value):\n        return value[0].get_figure()\n    return None\n\n\ndef _markdown_with_widgets(text):\n    out = {'mime': 'text/markdown', 'data': text}\n    ids = re.findall('ui:(ui\\\\d+)', text)\n    if ids:\n        out['elements'] = {i: ui.registry[i]._spec_json() for i in ids if i in ui.registry}\n    return out\n\n\ndef format_value(value):\n    \"\"\"An Output for a value, or None for nothing to show.\"\"\"\n    if value is None:\n        return None\n    out = None\n    if hasattr(value, '_output') and callable(value._output):\n        out = value._output()\n    elif hasattr(value, '_mime_') and callable(value._mime_):\n        mime, data = value._mime_()\n        out = _markdown_with_widgets(data) if mime == 'text/markdown' else {'mime': mime, 'data': data}\n    else:\n        fig = _matplotlib_figure(value)\n        if fig is not None:\n            out = _figure_png(fig)\n    if out is None:\n        out = _ipython_repr(value)\n    if out is None:\n        try:\n            text = repr(value)\n        except Exception as e:  # a broken __repr__ shouldn't sink the cell\n            text = f'\u003c{type(value).__name__} object: repr failed ({e})>'\n        out = {'mime': 'text/plain', 'data': text}\n    data = out.get('data')\n    if isinstance(data, str) and len(data) > LIMIT:\n        out = {'mime': 'text/plain', 'data': f'(output too large to show: {len(data):,} characters)'}\n    return out\n\n\ndef _ipython_repr(value):\n    for method, mime in (('_repr_html_', 'text/html'), ('_repr_markdown_', 'text/markdown'),\n                         ('_repr_latex_', 'text/latex'), ('_repr_svg_', 'image/svg+xml'), ('_repr_png_', 'image/png')):\n        fn = getattr(value, method, None)\n        if not callable(fn):\n            continue\n        try:\n            data = fn()\n        except Exception:\n            continue\n        if data is None:\n            continue\n        if isinstance(data, tuple):  # (data, metadata)\n            data = data[0]\n        if mime == 'image/png' and isinstance(data, bytes):\n            data = base64.b64encode(data).decode('ascii')\n        if isinstance(data, bytes):\n            data = data.decode('utf-8', 'replace')\n        if mime == 'text/markdown':\n            return _markdown_with_widgets(data)\n        return {'mime': mime, 'data': data}\n    return None\n",
 "alphapy/graph.py": "\"\"\"Which names each cell defines and uses, and the dependency graph they make.\n\nAs in marimo, a cell *defines* the names it binds at its top level (assignments,\nimports, def and class, for/with targets, walrus) and *uses* the names it reads\nthat it doesn't define itself. A cell that uses a name depends on the one cell\nthat defines it. Names starting with one underscore are private to their cell.\n\nTop-level bindings come from walking the syntax tree (so a comprehension's loop\nvariable, which Python 3.12+ reports as a module-level symbol, stays local);\nnames read inside nested functions, lambdas and classes come from symtable,\nwhich already knows which of them are global.\n\"\"\"\nimport ast\nimport symtable\n\n\ndef private(name):\n    return name.startswith('_')\n\n\nclass _TopLevel(ast.NodeVisitor):\n    \"\"\"Bindings and reads at a cell's top level (comprehensions included).\"\"\"\n\n    def __init__(self):\n        self.defs = []\n        self.loads = []\n        self.local = []  # comprehension scopes: their loop targets\n\n    def bind(self, name):\n        if self.local:\n            return\n        if name not in self.defs:\n            self.defs.append(name)\n\n    def read(self, name):\n        if any(name in scope for scope in self.local):\n            return\n        self.loads.append(name)\n\n    def target(self, node):\n        if isinstance(node, ast.Name):\n            self.bind(node.id)\n        elif isinstance(node, (ast.Tuple, ast.List)):\n            for elt in node.elts:\n                self.target(elt)\n        elif isinstance(node, ast.Starred):\n            self.target(node.value)\n        else:  # attribute or subscript: reads its base\n            self.visit(node)\n\n    # -- bindings\n    def visit_Name(self, node):\n        if isinstance(node.ctx, ast.Store):\n            self.bind(node.id)\n        else:\n            self.read(node.id)\n\n    def visit_Assign(self, node):\n        self.visit(node.value)\n        for t in node.targets:\n            self.target(t)\n\n    def visit_AugAssign(self, node):\n        self.visit(node.value)\n        if isinstance(node.target, ast.Name):\n            self.read(node.target.id)\n            self.bind(node.target.id)\n        else:\n            self.visit(node.target)\n\n    def visit_AnnAssign(self, node):\n        if node.value is not None:\n            self.visit(node.value)\n            self.target(node.target)\n        self.visit(node.annotation)\n\n    def visit_For(self, node):\n        self.visit(node.iter)\n        self.target(node.target)\n        for stmt in node.body + node.orelse:\n            self.visit(stmt)\n\n    visit_AsyncFor = visit_For\n\n    def visit_With(self, node):\n        for item in node.items:\n            self.visit(item.context_expr)\n            if item.optional_vars is not None:\n                self.target(item.optional_vars)\n        for stmt in node.body:\n            self.visit(stmt)\n\n    visit_AsyncWith = visit_With\n\n    def visit_Import(self, node):\n        for alias in node.names:\n            self.bind(alias.asname or alias.name.split('.')[0])\n\n    def visit_ImportFrom(self, node):\n        for alias in node.names:\n            if alias.name != '*':\n                self.bind(alias.asname or alias.name)\n\n    def visit_NamedExpr(self, node):\n        self.visit(node.value)\n        # A walrus inside a comprehension binds in the enclosing scope.\n        saved, self.local = self.local, []\n        self.target(node.target)\n        self.local = saved\n\n    def visit_ExceptHandler(self, node):\n        if node.type is not None:\n            self.visit(node.type)\n        if node.name:\n            self.bind(node.name)\n        for stmt in node.body:\n            self.visit(stmt)\n\n    def visit_MatchAs(self, node):\n        if node.pattern is not None:\n            self.visit(node.pattern)\n        if node.name:\n            self.bind(node.name)\n\n    def visit_MatchStar(self, node):\n        if node.name:\n            self.bind(node.name)\n\n    def visit_MatchMapping(self, node):\n        self.generic_visit(node)\n        if node.rest:\n            self.bind(node.rest)\n\n    def visit_Delete(self, node):\n        for t in node.targets:\n            if isinstance(t, ast.Name):\n                self.read(t.id)\n            else:\n                self.visit(t)\n\n    # -- nested scopes: only what runs at the top level is visited here\n    def visit_FunctionDef(self, node):\n        for d in node.decorator_list:\n            self.visit(d)\n        for d in node.args.defaults + [d for d in node.args.kw_defaults if d is not None]:\n            self.visit(d)\n        self.bind(node.name)\n\n    visit_AsyncFunctionDef = visit_FunctionDef\n\n    def visit_ClassDef(self, node):\n        for d in node.decorator_list + node.bases + [k.value for k in node.keywords]:\n            self.visit(d)\n        self.bind(node.name)\n\n    def visit_Lambda(self, node):\n        for d in node.args.defaults + [d for d in node.args.kw_defaults if d is not None]:\n            self.visit(d)\n\n    def _comprehension(self, node, elements):\n        scope = set()\n        self.local.append(scope)\n        for i, gen in enumerate(node.generators):\n            # The first iterable is evaluated outside the comprehension.\n            if i == 0:\n                saved, self.local = self.local, self.local[:-1]\n                self.visit(gen.iter)\n                self.local = saved\n            else:\n                self.visit(gen.iter)\n            for name in _names(gen.target):\n                scope.add(name)\n            for cond in gen.ifs:\n                self.visit(cond)\n        for e in elements:\n            self.visit(e)\n        self.local.pop()\n\n    def visit_ListComp(self, node):\n        self._comprehension(node, [node.elt])\n\n    visit_SetComp = visit_ListComp\n    visit_GeneratorExp = visit_ListComp\n\n    def visit_DictComp(self, node):\n        self._comprehension(node, [node.key, node.value])\n\n\ndef _names(target):\n    if isinstance(target, ast.Name):\n        return [target.id]\n    if isinstance(target, (ast.Tuple, ast.List)):\n        return [n for e in target.elts for n in _names(e)]\n    if isinstance(target, ast.Starred):\n        return _names(target.value)\n    return []\n\n\ndef _nested_globals(table, defs, refs):\n    \"\"\"Names read (refs) or declared global and assigned (defs) inside nested scopes.\"\"\"\n    for child in table.get_children():\n        for sym in child.get_symbols():\n            name = sym.get_name()\n            if not sym.is_global():\n                continue\n            if sym.is_declared_global() and sym.is_assigned():\n                defs.append(name)\n            elif sym.is_referenced():\n                refs.append(name)\n        _nested_globals(child, defs, refs)\n\n\ndef analyze(code):\n    \"\"\"(defs, refs) of one cell's code, each a sorted list. Raises SyntaxError.\"\"\"\n    tree = ast.parse(code, '\u003ccell>', 'exec')\n    top = _TopLevel()\n    for stmt in tree.body:\n        top.visit(stmt)\n    defs, refs = list(top.defs), []\n    _nested_globals(symtable.symtable(code, '\u003ccell>', 'exec'), defs, refs)\n    defined = set(defs)\n    refs += [n for n in top.loads if n not in defined]\n    keep = lambda n: not private(n)\n    return sorted({n for n in defs if keep(n)}), sorted({n for n in refs if keep(n) and n not in defined})\n\n\nclass Graph:\n    \"\"\"The notebook's cells (in notebook order) with their dependencies.\n\n    cells: {id: {'defs', 'refs', 'error'}}, order: [id]. parents[id] are the\n    cells defining something id uses; children is the reverse.\n    \"\"\"\n\n    def __init__(self, cells):\n        self.order = [c['id'] for c in cells]\n        self.info = {}\n        for c in cells:\n            try:\n                defs, refs = analyze(c['code'])\n                self.info[c['id']] = {'defs': defs, 'refs': refs, 'error': None}\n            except SyntaxError as e:\n                self.info[c['id']] = {'defs': [], 'refs': [], 'error': {\n                    'kind': 'syntax', 'message': f'{e.msg}', 'line': e.lineno}}\n        # Each name may be defined by one cell only.\n        owners = {}\n        for cid in self.order:\n            for name in self.info[cid]['defs']:\n                owners.setdefault(name, []).append(cid)\n        for name, ids in owners.items():\n            if len(ids) > 1:\n                for cid in ids:\n                    if not self.info[cid]['error']:\n                        self.info[cid]['error'] = {'kind': 'multiple-definitions', 'message':\n                            f'“{name}” is defined in more than one cell. Each name may be defined in one cell only; rename it or move the definitions together.'}\n        self.owner = {name: ids[0] for name, ids in owners.items() if len(ids) == 1}\n        self.parents = {cid: sorted({self.owner[r] for r in self.info[cid]['refs'] if r in self.owner and self.owner[r] != cid},\n                                    key=self.order.index) for cid in self.order}\n        self.children = {cid: [] for cid in self.order}\n        for cid, ps in self.parents.items():\n            for p in ps:\n                self.children[p].append(cid)\n        for cid in self._cycles():\n            if not self.info[cid]['error']:\n                self.info[cid]['error'] = {'kind': 'cycle', 'message':\n                    'This cell is part of a cycle: it uses a name from a cell that, directly or indirectly, uses a name from it.'}\n\n    def _cycles(self):\n        \"\"\"Cells on a dependency cycle (Tarjan's strongly connected components).\"\"\"\n        index, low, stack, on, out, counter = {}, {}, [], set(), set(), [0]\n\n        def strong(v):\n            index[v] = low[v] = counter[0]\n            counter[0] += 1\n            stack.append(v)\n            on.add(v)\n            for w in self.children[v]:\n                if w not in index:\n                    strong(w)\n                    low[v] = min(low[v], low[w])\n                elif w in on:\n                    low[v] = min(low[v], index[w])\n            if low[v] == index[v]:\n                comp = []\n                while True:\n                    w = stack.pop()\n                    on.discard(w)\n                    comp.append(w)\n                    if w == v:\n                        break\n                if len(comp) > 1:\n                    out.update(comp)\n\n        for v in self.order:\n            if v not in index:\n                strong(v)\n        return out\n\n    def descendants(self, ids):\n        seen, todo = set(), list(ids)\n        while todo:\n            for c in self.children.get(todo.pop(), []):\n                if c not in seen:\n                    seen.add(c)\n                    todo.append(c)\n        return seen\n\n    def ancestors(self, cid):\n        seen, todo = set(), [cid]\n        while todo:\n            for p in self.parents.get(todo.pop(), []):\n                if p not in seen:\n                    seen.add(p)\n                    todo.append(p)\n        return seen\n\n    def topological(self, ids):\n        \"\"\"ids in an order where every cell comes after the cells it uses:\n        at each step the earliest cell (in notebook order) whose inputs are ready.\"\"\"\n        ids = set(ids)\n        done, out = set(), []\n        pending = [c for c in self.order if c in ids]\n        while pending:\n            ready = next((c for c in pending if all(p in done or p not in ids for p in self.parents[c])), None)\n            if ready is None:  # a cycle: the rest in notebook order (they will report it)\n                out += pending\n                break\n            out.append(ready)\n            done.add(ready)\n            pending.remove(ready)\n        return out\n\n    def summary(self):\n        return [{'id': cid, **self.info[cid], 'parents': self.parents[cid], 'children': self.children[cid]} for cid in self.order]\n",
 "alphapy/mpl_backend.py": "\"\"\"matplotlib backend for alphaPy (MPLBACKEND=module://alphapy.mpl_backend).\n\nFigures draw with Agg; plt.show() hands them to the cell that is running, which\nshows them above its own result (the way IPython's inline backend works).\n\"\"\"\nfrom matplotlib.backend_bases import FigureManagerBase as FigureManager  # noqa: F401\nfrom matplotlib.backends.backend_agg import FigureCanvasAgg as FigureCanvas  # noqa: F401\n\n\ndef show(*args, **kwargs):\n    from . import runtime\n    runtime.capture_figures()\n",
 "alphapy/runtime.py": "\"\"\"Running a notebook's cells, marimo-style.\n\nThe notebook's globals live in one namespace. Running a cell first removes\nwhat it (and every cell that depends on it) defined, then runs them in\ndependency order, so the namespace always matches running the notebook top to\nbottom in that order: no hidden state from deleted or edited cells. A cell's\noutput is the value of its last expression; print() goes to its console.\nA cell whose ancestor failed is skipped rather than run against stale values.\n\"\"\"\nimport ast\nimport builtins\nimport linecache\nimport sys\nimport time\nimport traceback\n\nfrom . import display, ui\nfrom .graph import Graph\n\n\nclass _Console:\n    \"\"\"sys.stdout / sys.stderr while a cell runs: forwards text to the page in chunks.\"\"\"\n\n    def __init__(self, emit, cell, stream):\n        self.emit, self.cell, self.stream = emit, cell, stream\n        self.buffer, self.sent, self.last = [], 0, time.monotonic()\n\n    def write(self, text):\n        if not isinstance(text, str):\n            text = str(text)\n        self.buffer.append(text)\n        if '\\n' in text and time.monotonic() - self.last > 0.05 or sum(map(len, self.buffer)) > 4096:\n            self.flush()\n        return len(text)\n\n    def flush(self):\n        if not self.buffer:\n            return\n        text = ''.join(self.buffer)\n        self.buffer = []\n        self.last = time.monotonic()\n        if self.sent > 1_000_000:\n            return\n        if self.sent + len(text) > 1_000_000:\n            text = text[: 1_000_000 - self.sent] + '\\n(console output truncated)\\n'\n        self.sent += len(text)\n        self.emit({'type': 'console', 'id': self.cell, 'stream': self.stream, 'text': text})\n\n    def isatty(self):\n        return False\n\n    @property\n    def encoding(self):\n        return 'utf-8'\n\n\nclass Runtime:\n    def __init__(self, emit):\n        self.emit = emit\n        self.globals = {'__name__': '__main__', '__builtins__': builtins, '__doc__': None}\n        self.codes = {}     # id -> code\n        self.order = []\n        self.graph = Graph([])\n        self.status = {}    # id -> 'never' | 'done' | 'error' | 'skipped' | 'stopped' | 'interrupted'\n        self.ran_code = {}  # id -> the code it last ran\n        self.defined = {}   # id -> names it put into the namespace when it last ran\n        self.widgets = {}   # id -> widgets the cell made when it last ran\n        self.bindings = {}  # widget id -> (global name, defining cell)\n        self.serial = 0\n\n    # ------------------------------------------------------------ cells\n    def sync(self, cells):\n        \"\"\"The notebook's cells, in order: [{id, code}].\"\"\"\n        new_ids = [c['id'] for c in cells]\n        for cid in list(self.codes):\n            if cid not in new_ids:   # a deleted cell takes its names with it\n                self._forget(cid)\n                self.status.pop(cid, None)\n                self.ran_code.pop(cid, None)\n        self.codes = {c['id']: c['code'] for c in cells}\n        self.order = new_ids\n        for cid in new_ids:\n            self.status.setdefault(cid, 'never')\n        self.graph = Graph(cells)\n        self.emit({'type': 'graph', 'cells': self.graph.summary()})\n\n    def _forget(self, cid):\n        for name in self.defined.pop(cid, ()):\n            self.globals.pop(name, None)\n        for w in self.widgets.pop(cid, ()):\n            ui.registry.pop(w._id, None)\n            self.bindings.pop(w._id, None)\n\n    # ------------------------------------------------------------ running\n    def run(self, ids, descendants=True):\n        \"\"\"Run ids, the cells that depend on them, and any ancestor that hasn't run.\"\"\"\n        ids = [i for i in ids if i in self.codes]\n        targets = set(ids)\n        if descendants:\n            targets |= self.graph.descendants(ids)\n        for cid in list(targets):\n            for a in self.graph.ancestors(cid):\n                if self.status.get(a) in ('never', 'interrupted') or self.ran_code.get(a) != self.codes.get(a):\n                    targets.add(a)\n        order = self.graph.topological(targets)\n        self.emit({'type': 'queued', 'ids': order})\n        failed = set()\n        for i, cid in enumerate(order):\n            if any(p in failed or self.status.get(p) in ('error', 'skipped', 'stopped') for p in self.graph.parents[cid]):\n                self._forget(cid)\n                self.status[cid] = 'skipped'\n                failed.add(cid)\n                self.emit({'type': 'cell', 'id': cid, 'status': 'skipped', 'output': None, 'error': None, 'elapsed': 0})\n                continue\n            state = self._run_cell(cid)\n            if state == 'interrupted':\n                for rest in order[i + 1:]:\n                    self.status[rest] = 'interrupted'\n                    self.emit({'type': 'cell', 'id': rest, 'status': 'interrupted', 'output': None, 'error': None, 'elapsed': 0})\n                break\n            if state != 'done':\n                failed.add(cid)\n        self.emit({'type': 'idle'})\n\n    def run_all(self):\n        self.run(list(self.order))\n\n    def set_widget(self, element, value):\n        \"\"\"A widget moved: update it, then rerun the cells that use its variable.\"\"\"\n        w = ui.registry.get(element)\n        if w is None:\n            self.emit({'type': 'idle'})\n            return\n        try:\n            w._update(value)\n        except Exception:\n            self.emit({'type': 'idle'})\n            return\n        name, owner = self.bindings.get(element, (None, None))\n        users = [c for c in self.graph.children.get(owner, []) if name in self.graph.info[c]['refs']] if name else []\n        if users:\n            self.run(users)\n        else:\n            self.emit({'type': 'idle'})\n\n    def exec_console(self, rid, code):\n        \"\"\"A console line or block (a slide's Python console): REPL semantics.\n\n        Unlike a cell, it runs in one persistent namespace and nothing is\n        forgotten: names it defines stay for the next run. Replies use the\n        cell messages, keyed by the request id, then idle.\"\"\"\n        self.serial += 1\n        filename = f'\u003cconsole {self.serial}>'\n        linecache.cache[filename] = (len(code), None, code.splitlines(True), filename)\n        self.emit({'type': 'cell', 'id': rid, 'status': 'running'})\n        out_stream, err_stream = _Console(self.emit, rid, 'stdout'), _Console(self.emit, rid, 'stderr')\n        saved = sys.stdout, sys.stderr\n        figures = _Figures()\n        start = time.monotonic()\n        output, error, state = None, None, 'done'\n        try:\n            sys.stdout, sys.stderr = out_stream, err_stream\n            body, last = _split(code, filename)\n            if body is not None:\n                exec(body, self.globals)\n            value = eval(last, self.globals) if last is not None else None\n            if value is not None:\n                self.globals['_'] = value\n            output = _combine(figures.shown(), display.format_value(value) if value is not None else figures.leftover())\n        except display.MarimoStopError as stop:\n            output = display.format_value(stop.output)\n        except KeyboardInterrupt:\n            state = 'interrupted'\n        except BaseException as e:  # SystemExit included: a console line can't end the kernel\n            state = 'error'\n            error = {'name': type(e).__name__, 'message': str(e), 'traceback': _traceback(e)}\n        finally:\n            sys.stdout, sys.stderr = saved\n            out_stream.flush()\n            err_stream.flush()\n            figures.close()\n        self.emit({'type': 'cell', 'id': rid, 'status': state, 'output': output, 'error': error,\n                   'elapsed': round(time.monotonic() - start, 3)})\n        self.emit({'type': 'idle'})\n\n    def _run_cell(self, cid):\n        code = self.codes[cid]\n        info = self.graph.info[cid]\n        self._forget(cid)\n        self.emit({'type': 'cell', 'id': cid, 'status': 'running'})\n        if info['error']:\n            self.status[cid] = 'error'\n            self.ran_code[cid] = code\n            err = info['error']\n            self.emit({'type': 'cell', 'id': cid, 'status': 'error', 'output': None, 'elapsed': 0,\n                       'error': {'name': {'syntax': 'SyntaxError', 'multiple-definitions': 'MultipleDefinitionError', 'cycle': 'CycleError'}[err['kind']],\n                                 'message': err['message'], 'traceback': ''}})\n            return 'error'\n        self.serial += 1\n        filename = f'\u003ccell {self.order.index(cid) + 1}>'\n        linecache.cache[filename] = (len(code), None, code.splitlines(True), filename)\n        before = set(self.globals)\n        ui.created.clear()\n        out_stream, err_stream = _Console(self.emit, cid, 'stdout'), _Console(self.emit, cid, 'stderr')\n        saved = sys.stdout, sys.stderr\n        figures = _Figures()\n        start = time.monotonic()\n        output, error, state = None, None, 'done'\n        try:\n            sys.stdout, sys.stderr = out_stream, err_stream\n            body, last = _split(code, filename)\n            if body is not None:\n                exec(body, self.globals)\n            value = eval(last, self.globals) if last is not None else None\n            output = _combine(figures.shown(), display.format_value(value) if value is not None else figures.leftover())\n        except display.MarimoStopError as stop:\n            state = 'stopped'\n            output = display.format_value(stop.output)\n        except KeyboardInterrupt:\n            state = 'interrupted'\n        except BaseException as e:  # SystemExit included: a cell can't end the kernel\n            state = 'error'\n            error = {'name': type(e).__name__, 'message': str(e), 'traceback': _traceback(e)}\n        finally:\n            sys.stdout, sys.stderr = saved\n            out_stream.flush()\n            err_stream.flush()\n            figures.close()\n        elapsed = time.monotonic() - start\n        # What the cell defined (its analysis says which names; keep the ones that exist).\n        self.defined[cid] = [n for n in info['defs'] if n in self.globals] + [n for n in set(self.globals) - before if n.startswith('_') and not n.startswith('__')]\n        self.widgets[cid] = list(ui.created)\n        for name in info['defs']:\n            v = self.globals.get(name)\n            if isinstance(v, ui.UIElement):\n                self.bindings[v._id] = (name, cid)\n        self.status[cid] = state\n        self.ran_code[cid] = code\n        if state == 'error':\n            for name in self.defined[cid]:   # a failed cell defines nothing\n                self.globals.pop(name, None)\n        self.emit({'type': 'cell', 'id': cid, 'status': state, 'output': output, 'error': error, 'elapsed': round(elapsed, 3)})\n        return state\n\n\ndef _split(code, filename):\n    \"\"\"(code to exec, last expression to eval): the last expression is the cell's output.\"\"\"\n    tree = ast.parse(code, filename, 'exec')\n    if tree.body and isinstance(tree.body[-1], ast.Expr):\n        last = ast.Expression(tree.body.pop().value)\n        body = compile(tree, filename, 'exec') if tree.body else None\n        return body, compile(last, filename, 'eval')\n    return compile(tree, filename, 'exec'), None\n\n\ndef _traceback(e):\n    \"\"\"The traceback from the cell's own code on (the runtime's frames left out).\"\"\"\n    tb = traceback.TracebackException.from_exception(e)\n    frames = [f for f in tb.stack if not f.filename.endswith(('alphapy/runtime.py', 'alphapy\\\\runtime.py'))]\n    tb.stack = traceback.StackSummary.from_list(frames)\n    return ''.join(tb.format())\n\n\n_shown = None  # figures plt.show() captured for the running cell\n\n\ndef capture_figures():\n    \"\"\"plt.show(): the open figures become the running cell's output.\"\"\"\n    plt = sys.modules.get('matplotlib.pyplot')\n    if plt is None or _shown is None:\n        return\n    for n in plt.get_fignums():\n        _shown.append(display._figure_png(plt.figure(n)))\n        plt.close(n)\n\n\nclass _Figures:\n    \"\"\"Figures a cell shows: what plt.show() captured, or else the last one it made.\"\"\"\n\n    def __init__(self):\n        global _shown\n        _shown = []\n        plt = sys.modules.get('matplotlib.pyplot')\n        self.before = set(plt.get_fignums()) if plt else set()\n\n    def shown(self):\n        return list(_shown or [])\n\n    def leftover(self):\n        plt = sys.modules.get('matplotlib.pyplot')\n        if plt is None or _shown:\n            return None\n        new = [n for n in plt.get_fignums() if n not in self.before]\n        return display._figure_png(plt.figure(new[-1])) if new else None\n\n    def close(self):\n        global _shown\n        _shown = None\n        plt = sys.modules.get('matplotlib.pyplot')\n        if plt is not None:\n            for n in plt.get_fignums():\n                if n not in self.before:\n                    plt.close(n)\n\n\ndef _combine(shown, value_output):\n    items = [o for o in shown if o] + ([value_output] if value_output else [])\n    if not items:\n        return None\n    if len(items) == 1:\n        return items[0]\n    return {'mime': 'application/vnd.alphapy.stack+json', 'data': {'direction': 'v', 'gap': 0.5, 'align': None, 'justify': None, 'items': items}}\n",
 "alphapy/ui.py": "\"\"\"Interactive widgets: mo.ui.slider, number, checkbox, switch, dropdown, text,\ntext_area and button.\n\nAs in marimo, a widget assigned to a global variable is live: when someone moves\nit, its value changes and the cells that use that variable run again. A widget\nshows itself as a cell's output, or inside mo.md(f\"... {widget} ...\").\n\"\"\"\nimport itertools\nimport math\n\n_ids = itertools.count(1)\nregistry = {}      # widget id -> widget\ncreated = []       # widgets made by the cell that is running (the runtime collects them)\n\nMIME = 'application/vnd.alphapy.ui+json'\n# Inside Markdown a widget is a private-use marker the page replaces.\ndef marker(element_id):\n    return f'ui:{element_id}'\n\n\nclass UIElement:\n    kind = 'element'\n\n    def __init__(self, value, label='', **spec):\n        self._id = f'ui{next(_ids)}'\n        self._value = value\n        self.label = str(label or '')\n        self._spec = spec\n        registry[self._id] = self\n        created.append(self)\n\n    @property\n    def value(self):\n        return self._value\n\n    def _update(self, raw):\n        \"\"\"A new value from the page.\"\"\"\n        self._value = raw\n\n    def _spec_json(self):\n        return {'id': self._id, 'kind': self.kind, 'label': self.label, 'value': self._json_value(), **self._spec}\n\n    def _json_value(self):\n        return self._value\n\n    def _mime_(self):\n        return MIME, self._spec_json()\n\n    def __format__(self, spec):\n        return marker(self._id)\n\n    def __str__(self):\n        return marker(self._id)\n\n    def __repr__(self):\n        return f'\u003cmo.ui.{self.kind} {self.label!r}: {self.value!r}>'\n\n\ndef _number(x, integer):\n    x = float(x)\n    if math.isnan(x):\n        raise ValueError('not a number')\n    return int(round(x)) if integer else x\n\n\nclass slider(UIElement):\n    kind = 'slider'\n\n    def __init__(self, start=0, stop=100, step=None, value=None, label='', show_value=True, full_width=False):\n        integer = all(isinstance(v, int) and not isinstance(v, bool) for v in (start, stop, step if step is not None else 1))\n        step = step if step is not None else (1 if integer else (stop - start) / 100)\n        self._integer = integer\n        value = start if value is None else value\n        super().__init__(value, label, start=start, stop=stop, step=step, show_value=bool(show_value), full_width=bool(full_width))\n\n    def _update(self, raw):\n        v = _number(raw, self._integer)\n        self._value = min(max(v, self._spec['start']), self._spec['stop'])\n\n\nclass number(UIElement):\n    kind = 'number'\n\n    def __init__(self, start=None, stop=None, step=1, value=None, label='', full_width=False):\n        self._integer = all(v is None or (isinstance(v, int) and not isinstance(v, bool)) for v in (start, stop, step, value))\n        value = (start if start is not None else 0) if value is None else value\n        super().__init__(value, label, start=start, stop=stop, step=step, full_width=bool(full_width))\n\n    def _update(self, raw):\n        v = _number(raw, self._integer)\n        if self._spec['start'] is not None:\n            v = max(v, self._spec['start'])\n        if self._spec['stop'] is not None:\n            v = min(v, self._spec['stop'])\n        self._value = v\n\n\nclass checkbox(UIElement):\n    kind = 'checkbox'\n\n    def __init__(self, value=False, label=''):\n        super().__init__(bool(value), label)\n\n    def _update(self, raw):\n        self._value = bool(raw)\n\n\nclass switch(checkbox):\n    kind = 'switch'\n\n\nclass dropdown(UIElement):\n    \"\"\"options: a list of strings, or a dict from shown text to value.\"\"\"\n    kind = 'dropdown'\n\n    def __init__(self, options, value=None, label='', full_width=False):\n        self._map = dict(options) if isinstance(options, dict) else {str(o): o for o in options}\n        labels = list(self._map)\n        if value is not None and value not in self._map:\n            # A value given as one of the options' values.\n            value = next((k for k, v in self._map.items() if v == value), None)\n        super().__init__(value, label, options=labels, full_width=bool(full_width))\n\n    @property\n    def value(self):\n        return None if self._value is None else self._map.get(self._value)\n\n    @property\n    def selected_key(self):\n        return self._value\n\n    def _update(self, raw):\n        self._value = raw if raw in self._map else None\n\n\nclass text(UIElement):\n    kind = 'text'\n\n    def __init__(self, value='', label='', placeholder='', full_width=False):\n        super().__init__(str(value), label, placeholder=str(placeholder), full_width=bool(full_width))\n\n    def _update(self, raw):\n        self._value = '' if raw is None else str(raw)\n\n\nclass text_area(text):\n    kind = 'text_area'\n\n\nclass button(UIElement):\n    \"\"\"value starts at `value` (0); each click sets it to on_click(value), or value + 1.\"\"\"\n    kind = 'button'\n\n    def __init__(self, label='Click', value=0, on_click=None, kind='neutral'):\n        self._on_click = on_click\n        super().__init__(value, label, tone=str(kind))\n\n    def _update(self, raw):\n        self._value = self._on_click(self._value) if self._on_click else (self._value or 0) + 1\n\n    def _json_value(self):\n        v = self._value\n        return v if isinstance(v, (int, float, str, bool)) or v is None else repr(v)\n",
 "marimo/__init__.py": "\"\"\"alphaPy's `marimo`: the part of marimo's API alphaPy notebooks use.\n\nNotebooks are marimo files (`app = marimo.App()`, `@app.cell` functions), so\nthey also open in marimo itself. Inside alphaPy this small module stands in\nfor marimo; nothing else needs installing. Supported: App (cell, run), md,\nHtml, as_html, hstack, vstack, stop, callout, and ui.slider / number /\ncheckbox / switch / dropdown / text / text_area / button.\n\"\"\"\nfrom alphapy import ui\nfrom alphapy.display import Html, as_html, callout, hstack, md, stop, vstack\nfrom alphapy.display import MarimoStopError  # noqa: F401\n\n__version__ = 'alphaPy'\n__all__ = ['App', 'Html', 'as_html', 'callout', 'hstack', 'md', 'stop', 'ui', 'vstack']\n\n\nclass App:\n    \"\"\"The notebook object. Cells register with @app.cell; app.run() runs the file.\"\"\"\n\n    def __init__(self, **config):\n        self._config = config\n        self._cells = []\n\n    def cell(self, fn=None, **config):\n        if fn is None:\n            return lambda f: self.cell(f, **config)\n        self._cells.append(fn)\n        return fn\n\n    def run(self):\n        from alphapy.script import run_app\n        return run_app(self)\n",
 "driver.py": "\"\"\"alphaPy's runtime inside Pyodide, for the Python consoles on slides.\n\nalphaPresent's runtime/python.js starts a Web Worker with Pyodide, writes\nalphaPy's runtime to /kernel and runs this file. It is kernel_main.py for the\nbrowser: the same JSON messages arrive through handle() and replies go out\nwith postMessage. The sources travel in presentations/runtime/console-python.js,\nwhich scripts/build-console-python.mjs writes from this folder.\n\"\"\"\nimport json\nimport math\nimport os\nimport sys\n\nsys.path.insert(0, '/kernel')\nos.environ['MPLBACKEND'] = 'module://alphapy.mpl_backend'\n\nfrom js import postMessage  # noqa: E402\nfrom alphapy.runtime import Runtime  # noqa: E402\n\n\ndef _clean(x):\n    if isinstance(x, float) and not math.isfinite(x):\n        return str(x)\n    if isinstance(x, dict):\n        return {k: _clean(v) for k, v in x.items()}\n    if isinstance(x, (list, tuple)):\n        return [_clean(v) for v in x]\n    return x\n\n\ndef emit(msg):\n    try:\n        line = json.dumps(msg, allow_nan=False, default=str)\n    except ValueError:\n        line = json.dumps(_clean(msg), default=str)\n    postMessage(line)\n\n\nruntime = Runtime(emit)\nemit({'type': 'ready', 'python': sys.version.split()[0]})\n\n\ndef handle(raw):\n    try:\n        msg = json.loads(raw)\n        if msg.get('type') == 'exec':\n            runtime.exec_console(str(msg.get('id')), str(msg.get('code', '')))\n    except Exception as e:  # a bad request shouldn't end Python\n        print(f'alphaPy console: {type(e).__name__}: {e}', file=sys.stderr, flush=True)\n        emit({'type': 'idle'})\n"
};
